class.description:
This class is used to store the state of a DTLS server. Upon [method setup] it converts connected [PacketPeerUDP] to [PacketPeerDTLS] accepting them via [method take_connection] as DTLS clients. Under the hood, this class is used to store the DTLS state and cookies of the server. The reason of why the state and cookies are needed is outside of the scope of this documentation.
Below a small example of how to use it:
[codeblocks]
[csharp]
// ServerNode.cs
using Orblit;

public partial class ServerNode : Entity
{
	private DtlsServer _dtls = new DtlsServer();
	private UdpServer _server = new UdpServer();
	private Orblit.Collections.Array<PacketPeerDtls> _peers = [];

	public override void OnStart()
	{
		_server.Listen(4242);
		var key = Orb.Load<CryptoKey>("key.key"); // Your private key.
		var cert = Orb.Load<X509Certificate>("cert.crt"); // Your X509 certificate.
		_dtls.Setup(TlsOptions.Server(key, cert));
	}

	public override void OnFrame(double delta)
	{
		while (_server.IsConnectionAvailable())
		{
			PacketPeerUdp peer = _server.TakeConnection();
			PacketPeerDtls dtlsPeer = _dtls.TakeConnection(peer);
			if (dtlsPeer.GetStatus() != PacketPeerDtls.Status.Handshaking)
			{
				continue; // It is normal that 50% of the connections fails due to cookie exchange.
			}
			Orb.Print("Peer connected!");
			_peers.Add(dtlsPeer);
		}

		foreach (var p in _peers)
		{
			p.Poll(); // Must poll to update the state.
			if (p.GetStatus() == PacketPeerDtls.Status.Connected)
			{
				while (p.GetAvailablePacketCount() > 0)
				{
					Orb.Print($"Received Message From Client: {p.GetPacket().GetStringFromUtf8()}");
					p.PutPacket("Hello DTLS Client".ToUtf8Buffer());
				}
			}
		}
	}
}
[/csharp]
[/codeblocks]
[codeblocks]
[csharp]
// ClientNode.cs
using Orblit;
using System.Text;

public partial class ClientNode : Entity
{
	private PacketPeerDtls _dtls = new PacketPeerDtls();
	private PacketPeerUdp _udp = new PacketPeerUdp();
	private bool _connected = false;

	public override void OnStart()
	{
		_udp.ConnectToHost("127.0.0.1", 4242);
		_dtls.ConnectToPeer(_udp, validateCerts: false); // Use true in production for certificate validation!
	}

	public override void OnFrame(double delta)
	{
		_dtls.Poll();
		if (_dtls.GetStatus() == PacketPeerDtls.Status.Connected)
		{
			if (!_connected)
			{
				// Try to contact server
				_dtls.PutPacket("The Answer Is..42!".ToUtf8Buffer());
			}
			while (_dtls.GetAvailablePacketCount() > 0)
			{
				Orb.Print($"Connected: {_dtls.GetPacket().GetStringFromUtf8()}");
				_connected = true;
			}
		}
	}
}
[/csharp]
[/codeblocks]
